// =============================================
// SPI Master Testbench - Auto-generated by SPI Customizer
// =============================================

`timescale 1ns / 1ps

module spi_master_tb;

    // Parameters
    parameter MODE = 3;
    parameter DATA_WIDTH = 16;
    parameter NUM_SLAVES = 8;
    parameter SELECTED_SLAVE = 3;
    parameter SLAVE_ACTIVE_LOW = 1;
    parameter MSB_FIRST = 1;
    parameter FIFO_DEPTH = 32;
    parameter CLOCK_DIVIDER = 4;
    parameter DEFAULT_DATA_ENABLED = 0;
    parameter DEFAULT_DATA_PATTERN = "a5a5";
    parameter DEFAULT_DATA_VALUE = 16'hA5A5;

    // Signals
    reg clk;
    reg rst_n;
    reg start_tx;
    reg start_rx;
    reg [DATA_WIDTH-1:0] tx_data;
    wire [DATA_WIDTH-1:0] rx_data;
    wire busy;
    wire sclk;
    wire mosi;
    reg miso;
    wire [NUM_SLAVES-1:0] ss_n;
    wire irq;
    integer timeout_cycles;
    integer ss_idx;
    localparam SS_ACTIVE = SLAVE_ACTIVE_LOW ? 1'b0 : 1'b1;
    localparam SS_INACTIVE = ~SS_ACTIVE;

    // DUT instantiation
    spi_master #(
        .MODE(MODE),
        .DATA_WIDTH(DATA_WIDTH),
        .NUM_SLAVES(NUM_SLAVES),
        .SELECTED_SLAVE(SELECTED_SLAVE),
        .SLAVE_ACTIVE_LOW(SLAVE_ACTIVE_LOW),
        .MSB_FIRST(MSB_FIRST),
        .FIFO_DEPTH(FIFO_DEPTH),
        .CLOCK_DIVIDER(CLOCK_DIVIDER),
        .DEFAULT_DATA_ENABLED(DEFAULT_DATA_ENABLED),
        .DEFAULT_DATA_PATTERN(DEFAULT_DATA_PATTERN),
        .DEFAULT_DATA_VALUE(DEFAULT_DATA_VALUE)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .start_tx(start_tx),
        .start_rx(start_rx),
        .tx_data(tx_data),
        .rx_data(rx_data),
        .busy(busy),
        .sclk(sclk),
        .mosi(mosi),
        .miso(miso),
        .ss_n(ss_n),
        .irq(irq)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #10 clk = ~clk;  // 50MHz clock
    end

    // Deterministic wait helper to prevent hanging simulations.
    task wait_for_not_busy;
        input [255:0] tag;
        input integer max_cycles;
        begin
            timeout_cycles = 0;
            while (busy && timeout_cycles < max_cycles) begin
                #20;
                timeout_cycles = timeout_cycles + 1;
            end
            if (busy) begin
                $fatal(1, "Timeout waiting for busy deassertion during %0s", tag);
            end
        end
    endtask

    task wait_for_busy_assert;
        input [255:0] tag;
        input integer max_cycles;
        begin
            timeout_cycles = 0;
            while (!busy && timeout_cycles < max_cycles) begin
                #20;
                timeout_cycles = timeout_cycles + 1;
            end
            if (!busy) begin
                $fatal(1, "Timeout waiting for busy assertion during %0s", tag);
            end
        end
    endtask

    task assert_selected_ss_active;
        input [255:0] tag;
        begin
            if (ss_n[SELECTED_SLAVE] !== SS_ACTIVE) begin
                $fatal(1, "Selected SS index %0d not active during %0s", SELECTED_SLAVE, tag);
            end
            for (ss_idx = 0; ss_idx < NUM_SLAVES; ss_idx = ss_idx + 1) begin
                if (ss_idx != SELECTED_SLAVE && ss_n[ss_idx] !== SS_INACTIVE) begin
                    $fatal(1, "Non-selected SS index %0d active during %0s", ss_idx, tag);
                end
            end
        end
    endtask

    task assert_all_ss_inactive;
        input [255:0] tag;
        begin
            for (ss_idx = 0; ss_idx < NUM_SLAVES; ss_idx = ss_idx + 1) begin
                if (ss_n[ss_idx] !== SS_INACTIVE) begin
                    $fatal(1, "SS index %0d not inactive during %0s", ss_idx, tag);
                end
            end
        end
    endtask

    // Test sequence for master mode
    initial begin
        // Initialize
        rst_n = 0;
        start_tx = 0;
        start_rx = 0;
        tx_data = 0;
        miso = 0;

        #100;
        rst_n = 1;
        #200;  // Allow system to stabilize

        $display("=== SPI Master RTL Testbench Starting ===");
        $display("Configuration: Mode %d, %d-bit data, %d slaves", MODE, DATA_WIDTH, NUM_SLAVES);

        // Test core SPI functionality (optimized for speed)
        $display("--- Testing Core SPI Functionality ---");

        // Test 1: Basic data transmission
        
        
        tx_data = 16'hAA55;
        
        $display("TX Data: 0x%h", tx_data);
        start_tx = 1;
        #50;
        start_tx = 0;
        wait_for_busy_assert("test1_tx", 2000);
        assert_selected_ss_active("test1_tx");

        wait_for_not_busy("test1_tx", 20000);
        assert_all_ss_inactive("test1_tx_complete");
        $display("✓ Transmission complete");

        // Brief delay between transactions
        #200;
        

        // Test 2: Different data pattern (test MSB/LSB order)
        
        tx_data = 16'h5555;
        
        $display("TX Data: 0x%h", tx_data);
        start_tx = 1;
        #50;
        start_tx = 0;
        wait_for_busy_assert("test2_tx", 2000);
        assert_selected_ss_active("test2_tx");

        wait_for_not_busy("test2_tx", 20000);
        assert_all_ss_inactive("test2_tx_complete");
        $display("✓ Second transmission complete");

        // Test reception (simplified for speed)
        $display("--- Testing Reception ---");

        
        // Prepare to receive data from selected slave index
        $display("Target slave index: %0d", SELECTED_SLAVE);
        start_rx = 1;
        #50;
        start_rx = 0;
        wait_for_busy_assert("test_rx", 2000);
        assert_selected_ss_active("test_rx");

        // Simulate slave providing response data
        #200;
        miso = 1'b1;  // Data bit based on CPHA

        wait_for_not_busy("test_rx", 20000);
        assert_all_ss_inactive("test_rx_complete");
        $display("✓ Reception complete");
        

        // Test 3: Quick burst transmission (simplified)
        $display("--- Testing Burst Transmission ---");
        tx_data = 16'hFF00;
        $display("Burst TX: 0x%h", tx_data);
        start_tx = 1;
        #50;
        start_tx = 0;
        wait_for_busy_assert("test3_burst", 2000);
        assert_selected_ss_active("test3_burst");

        wait_for_not_busy("test3_burst", 20000);
        assert_all_ss_inactive("test3_burst_complete");
        $display("✓ Burst transmission complete");

        // Test 4: Quick configuration test
        $display("--- Testing Configuration ---");
        
        tx_data = 16'hABCD;
        
        $display("Config TX: 0x%h", tx_data);
        start_tx = 1;
        #50;
        start_tx = 0;
        wait_for_busy_assert("test4_config", 2000);
        assert_selected_ss_active("test4_config");

        wait_for_not_busy("test4_config", 20000);
        assert_all_ss_inactive("test4_config_complete");
        $display("✓ Configuration test complete");

        $display("=== All Master Tests Completed Successfully ===");
        $finish;
    end

    // VCD dumping
    initial begin
        $dumpfile("results/issue-58/data/spi_waveform.vcd");
        $dumpvars(0, spi_master_tb);
    end

endmodule